def add_item(items, name, qty):
    found = False
    for i in range(len(items)):
        if items[i]['name'] == name:
            items[i]['qty'] = items[i]['qty'] + qty
            found = True
    if not found:
        items.append({'name': name, 'qty': qty})
    return items

def remove_item(items, name, qty):
    for i in range(len(items)):
        if items[i]['name'] == name:
            items[i]['qty'] = items[i]['qty'] - qty
            if items[i]['qty'] <= 0:
                items.pop(i)
            break
    return items

def total_items(items):
    t = 0
    for item in items:
        t = t + item['qty']
    return t
